package cn.richie696.component.secret.provider.kmip;
import cn.richie696.component.secret.bootstrap.*; import cn.richie696.component.secret.starter.SecretRuntimeAutoConfiguration; import org.springframework.boot.autoconfigure.*; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Bean;
@AutoConfiguration @AutoConfigureBefore(SecretRuntimeAutoConfiguration.class) @ConditionalOnProperty(prefix=BootstrapSecretProperties.PREFIX,name="enabled",havingValue="true") public class KmipSecretAutoConfiguration { @Bean(destroyMethod="close") @ConditionalOnBean(SecretBootstrapState.class) @ConditionalOnMissingBean(KmipSecretClient.class) KmipSecretClient kmipSecretClient(SecretBootstrapState state){if(!(state.client() instanceof KmipSecretClient c))throw new IllegalStateException("KMIP bootstrap client is not available");return c;} }
